129	      return fail("UXB_OFFSETOF_METADATA_REQUIRED", "OFFSETOF requires emitted layout metadata");
130	    },
131	    pointerOf() {
132	      return fail("UXB_POINTER_UNAVAILABLE", "pointer values are not available on the JavaScript target");
133	    },
134	    builtin(name, args = []) {
135	      const op = String(name || "").toUpperCase();
136	      const a = Array.isArray(args) ? args : [];
137	      switch (op) {
138	        case "ABS": return Math.abs(Number(a[0] || 0));
139	        case "SQR":
140	        case "SQRT": return Math.sqrt(Number(a[0] || 0));
141	        case "SIN": return Math.sin(Number(a[0] || 0));
142	        case "COS": return Math.cos(Number(a[0] || 0));
143	        case "TAN": return Math.tan(Number(a[0] || 0));
144	        case "ATN": return Math.atan(Number(a[0] || 0));
145	        case "LOG": return Math.log(Number(a[0] || 0));
146	        case "EXP": return Math.exp(Number(a[0] || 0));
147	        case "FIX":
148	        case "INT":
149	        case "CINT":
150	        case "CLNG": return Math.trunc(Number(a[0] || 0));
151	        case "CSNG":
152	        case "CDBL":
153	        case "VAL": return Number(a[0] || 0);
154	        case "SGN": return Math.sign(Number(a[0] || 0));
155	        case "RND": return uxb.random.next();
156	        case "TIMER": return uxb.time.timer();
